[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "qr-scanner-screen",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "qr-scanner-screen",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "children": [
            {
              "id": "header",
              "type": "Row",
              "properties": {
                "mainAxisAlignment": "center",
                "padding": {
                  "top": 16,
                  "bottom": 16
                }
              },
              "children": [
                {
                  "id": "screen_title",
                  "type": "Text",
                  "properties": {
                    "text": "QR Scanner",
                    "style": "headlineSmall"
                  }
                }
              ]
            },
            {
              "id": "scanner_area",
              "type": "Stack",
              "properties": {
                "grow": 1
              },
              "children": [
                {
                  "id": "camera_feed_placeholder",
                  "type": "Box",
                  "properties": {
                    "backgroundColor": "#000000"
                  }
                },
                {
                  "id": "viewfinder_overlay",
                  "type": "Center",
                  "children": [
                    {
                      "id": "viewfinder_column",
                      "type": "Column",
                      "properties": {
                        "crossAxisAlignment": "center"
                      },
                      "children": [
                        {
                          "id": "viewfinder_frame",
                          "type": "Box",
                          "properties": {
                            "width": 280,
                            "height": 280,
                            "border": {
                              "width": 2,
                              "color": "#FFFFFF"
                            },
                            "cornerRadius": 16
                          }
                        },
                        {
                          "id": "viewfinder_text",
                          "type": "Text",
                          "properties": {
                            "text": "Align QR code within the frame",
                            "style": "bodyMedium",
                            "color": "#FFFFFF",
                            "padding": {
                              "top": 16
                            }
                          }
                        }
                      ]
                    }
                  ]
                },
                {
                  "id": "gallery_button",
                  "type": "IconButton",
                  "properties": {
                    "icon": "photo_library",
                    "alignment": "topLeft",
                    "padding": {
                      "top": 16,
                      "left": 16
                    }
                  }
                },
                {
                  "id": "flash_toggle",
                  "type": "IconButton",
                  "properties": {
                    "icon": "flash_off",
                    "alignment": "topRight",
                    "padding": {
                      "top": 16,
                      "right": 16
                    }
                  }
                }
              ]
            },
            {
              "id": "bottom_nav_bar",
              "type": "BottomNavigationBar",
              "children": [
                {
                  "id": "nav_scan",
                  "type": "BottomNavigationBarItem",
                  "properties": {
                    "icon": "qr_code_scanner",
                    "label": "Scan",
                    "selected": true
                  }
                },
                {
                  "id": "nav_history",
                  "type": "BottomNavigationBarItem",
                  "properties": {
                    "icon": "history",
                    "label": "History"
                  }
                },
                {
                  "id": "nav_settings",
                  "type": "BottomNavigationBarItem",
                  "properties": {
                    "icon": "settings",
                    "label": "Settings"
                  }
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
